wrapper_template:
case "${1:-}" in
  cat)
    [ -z "${2:-}" ] && { echo "Usage: filesystem.sh cat <path>" >&2; exit 1; }
    cat "$2" | head -n "$MAX_LINES"
    ;;
  head)
    [ -z "${2:-}" ] && { echo "Usage: filesystem.sh head <path> [lines]" >&2; exit 1; }
    head -n "${3:-50}" "$2"
    ;;
  tail)
    [ -z "${2:-}" ] && { echo "Usage: filesystem.sh tail <path> [lines]" >&2; exit 1; }
    tail -n "${3:-50}" "$2"
    ;;
  ls)
    ls -la "${2:-.}" | head -n "$MAX_LINES"
    ;;
  stat)
    [ -z "${2:-}" ] && { echo "Usage: filesystem.sh stat <path>" >&2; exit 1; }
    stat "$2"
    ;;
  find)
    [ -z "${3:-}" ] && { echo "Usage: filesystem.sh find <path> <pattern>" >&2; exit 1; }
    find "$2" -name "$3" 2>/dev/null | head -n "$MAX_LINES"
    ;;
  tree)
    if command -v tree >/dev/null 2>&1; then
      tree "${2:-.}" -L 3 | head -n "$MAX_LINES"
    else
      find "${2:-.}" -maxdepth 3 -print | head -n "$MAX_LINES"
    fi
    ;;
  write)
    [ -z "${3:-}" ] && { echo "Usage: filesystem.sh write <path> <content>" >&2; exit 1; }
    printf '%s' "$3" > "$2" && echo "Written: $2"
    ;;
  mkdir)
    [ -z "${2:-}" ] && { echo "Usage: filesystem.sh mkdir <path>" >&2; exit 1; }
    mkdir -p "$2" && echo "Created: $2"
    ;;
  mv)
    [ -z "${3:-}" ] && { echo "Usage: filesystem.sh mv <source> <destination>" >&2; exit 1; }
    mv -n "$2" "$3" && echo "Moved: $2 -> $3"
    ;;
  edit)
    [ -z "${4:-}" ] && { echo "Usage: filesystem.sh edit <path> <old_text> <new_text>" >&2; exit 1; }
    sed -i'' "s|$3|$4|" "$2" && echo "Edited: $2"
    ;;
